class StackError(RuntimeError):
    """可预期的启动/停止失败（消息不含密钥）。"""


def log(message: str) -> None:
    print(f"[local-stack] {message}", flush=True)


def run_cmd(cmd, timeout: float, env=None, cwd=None):
    try:
        return subprocess.run(
            [str(part) for part in cmd],
            cwd=str(cwd) if cwd else None,
            env=env,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout,
            creationflags=CREATE_NO_WINDOW,
        )
    except FileNotFoundError as exc:
        raise StackError(f"命令不存在：{cmd[0]}") from exc
    except subprocess.TimeoutExpired as exc:
        raise StackError(f"命令超时（{timeout:.0f}s）：{Path(str(cmd[0])).name}") from exc


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    return sha256_bytes(path.read_bytes())


def secure_path(path: Path, is_dir: bool = False) -> None:
    """任务临时目录/敏感备份仅当前用户可访问；失败不阻塞主流程。"""
    if os.name != "nt":
        return
    user = os.environ.get("USERNAME")
    if not user:
        return
    grant = f"{user}:(OI)(CI)F" if is_dir else f"{user}:F"
    try:
        subprocess.run(
            ["icacls", str(path), "/inheritance:r", "/grant:r", grant],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=10,
            creationflags=CREATE_NO_WINDOW,
        )
    except Exception:
        pass


