    except StackError:
        return set()
    pids: set[int] = set()
    for line in (result.stdout or "").splitlines():
        parts = line.split()
        if len(parts) < 5:
            continue
        local = parts[1]
        if local.rsplit(":", 1)[-1] != str(port):
            continue
        foreign = parts[2]
        if not foreign.endswith(":0") and "LISTENING" not in line.upper():
            continue
        try:
            pids.add(int(parts[-1]))
        except ValueError:
            pass
    return pids


